17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.Map;
25	import java.util.Set;
26	import java.util.concurrent.ConcurrentHashMap;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.FiscalYearResolver;
34	import org.springframework.samples.petclinic.mapper.HouseholdResolver;
35	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
36	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
37	import org.springframework.samples.petclinic.mapper.OwnerMapper;
38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.Region;
40	import org.springframework.samples.petclinic.mapper.SoundexResolver;
41	import org.springframework.samples.petclinic.mapper.VisitMapper;
42	import org.springframework.samples.petclinic.model.Owner;
43	import org.springframework.samples.petclinic.model.Pet;
44	import org.springframework.samples.petclinic.model.Visit;
45	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
46	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
47	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
48	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
49	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
50	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
51	import org.springframework.samples.petclinic.rest.api.OwnersApi;
52	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
53	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
54	import org.springframework.samples.petclinic.rest.dto.PetDto;
55	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
56	import org.springframework.samples.petclinic.rest.dto.VisitDto;
57	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
58	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
59	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
60	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
61	import org.springframework.samples.petclinic.service.ClinicService;
62	import org.springframework.security.access.prepost.PreAuthorize;
63	import org.springframework.web.bind.annotation.CrossOrigin;
64	import org.springframework.web.bind.annotation.RequestMapping;
65	import org.springframework.web.bind.annotation.RestController;
66	import org.springframework.web.util.UriComponentsBuilder;
67	
68	import jakarta.servlet.http.HttpServletRequest;
69	import jakarta.transaction.Transactional;
70	
71	/**
72	 * @author Vitaliy Fedoriv
73	 */
74	
75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
84	    private static final int MAX_OWNERS_PER_CITY = 50;
85	
86	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
87	    private static final int MAX_OWNERS_PER_DAY = 100;
88	
89	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
90	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
91	
92	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
93	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
94	
95	    /**
96	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
97	     * create with an already-seen key returns the original owner instead of creating a duplicate.
98	     */
99	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
100	
101	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
102	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
103	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
104	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
105	
106	    private final ClinicService clinicService;
107	
108	    private final OwnerMapper ownerMapper;
109	
110	    private final PetMapper petMapper;
111	
112	    private final VisitMapper visitMapper;
113	
114	    private final TelephoneNormalizer telephoneNormalizer;
115	
116	    private final AddressNormalizer addressNormalizer;
117	
118	    private final EmailNormalizer emailNormalizer;
119	
120	    private final IdentityKeyResolver identityKeyResolver;
121	
122	    private final HouseholdResolver householdResolver;
123	
124	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
125	    private final HttpServletRequest request;
126	
127	    public OwnerRestControllerV1(ClinicService clinicService,
128	                                 OwnerMapper ownerMapper,
129	                                 PetMapper petMapper,
130	                                 VisitMapper visitMapper,
131	                                 TelephoneNormalizer telephoneNormalizer,
132	                                 AddressNormalizer addressNormalizer,
133	                                 EmailNormalizer emailNormalizer,
134	                                 IdentityKeyResolver identityKeyResolver,
135	                                 HouseholdResolver householdResolver,
136	                                 HttpServletRequest request) {
137	        this.clinicService = clinicService;
138	        this.ownerMapper = ownerMapper;
139	        this.petMapper = petMapper;
140	        this.visitMapper = visitMapper;
141	        this.telephoneNormalizer = telephoneNormalizer;
142	        this.addressNormalizer = addressNormalizer;
143	        this.emailNormalizer = emailNormalizer;
144	        this.identityKeyResolver = identityKeyResolver;
145	        this.householdResolver = householdResolver;
146	        this.request = request;
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
152	        Collection<Owner> owners;
153	        if (lastName != null) {
154	            owners = this.clinicService.findOwnerByLastName(lastName);
155	        } else {
156	            owners = this.clinicService.findAllOwners();
157	        }
158	        if (owners.isEmpty()) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        owners.forEach(this::populateHouseholdMemberCount);
162	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
163	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        populateHouseholdMemberCount(owner);
174	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
175	    }
176	
177	    /**
178	     * Maps an owner to its DTO and stamps on the two derived values the mapper cannot produce on its own, each because
179	     * it depends on more than the single owner: the {@code identityKey} (see
180	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner, and the household-capped
181	     * {@code membershipLevel} (see {@link #cappedMembershipLevel}), which the mapper derives from the owner alone but
182	     * which the ceiling rule then caps against the owner's fellow household members. The capped level replaces the
183	     * mapper's uncapped one on the returned DTO.
184	     *
185	     * @param owner the owner to map
186	     * @return the owner DTO carrying its identity key and household-capped membership level
187	     */
188	    private OwnerDto toOwnerDto(Owner owner) {
189	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
190	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
191	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
192	        return ownerDto;
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Transactional
197	    @Override
198	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
199	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
200	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
201	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
202	            if (replay != null) {
203	                return replay;
204	            }
205	        }
206	        Owner owner = createOwner(ownerFieldsDto);
207	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
208	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
209	        }
210	        return createdOwnerResponse(owner);
211	    }
212	
213	    /**
214	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
215	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
216	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
217	     * normally.
218	     *
219	     * @param idempotencyKey the client-supplied idempotency key from the request header
220	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
221	     */
222	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
223	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
224	        if (existingId == null) {
225	            return null;
226	        }
227	        Owner owner = this.clinicService.findOwnerById(existingId);
228	        if (owner == null) {
229	            return null;
230	        }
231	        populateHouseholdMemberCount(owner);
232	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
233	    }
234	
235	    /**
236	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
237	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
238	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
239	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
240	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
241	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
242	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
243	     *
244	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
245	     * @return the newly created, persisted owner
246	     */
247	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
248	        normalizeAndValidate(ownerFieldsDto);
249	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
250	        populateDerivedFields(owner, ownerFieldsDto);
251	        requireUniqueIdentity(owner);
252	        flagPossibleDuplicate(owner, ownerFieldsDto);
253	        this.clinicService.saveOwner(owner);
254	        populateHouseholdMemberCount(owner);
255	        auditOwnerCreated(owner);
256	        return owner;
257	    }
258	
259	    /**
260	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
261	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
262	     * canonical URL.
263	     *
264	     * @param owner the newly created, persisted owner
265	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
266	     */
267	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
268	        OwnerDto ownerDto = toOwnerDto(owner);
269	        HttpHeaders headers = new HttpHeaders();
270	        headers.setLocation(UriComponentsBuilder.newInstance()
271	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
272	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
273	    }
274	
275	    /**
276	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
277	     * its id, customer code and registration date alongside the two values derived purely for the audit trail: the
278	     * membership level (see {@link MembershipLevelResolver#deriveMembershipLevel}) and the membership number, the
279	     * customer code suffixed with {@code -M} and the two-digit fiscal year of the registration date (see
280	     * {@link FiscalYearResolver#fiscalYear}).
281	     *
282	     * @param owner the newly created, persisted owner, with all its derived fields already in place
283	     */
284	    private void auditOwnerCreated(Owner owner) {
285	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
286	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
287	            MembershipLevelResolver.deriveMembershipLevel(owner),
288	            owner.getCustomerCode() + "-M" + String.format("%02d",
289	                FiscalYearResolver.fiscalYear(owner.getRegistrationDate()) % 100));
290	    }
291	
292	    /**
293	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
294	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
295	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
296	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
297	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
298	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
299	     * last name and postcode, so it is in place before the owner's household membership level is capped (see
300	     * {@link #cappedMembershipLevel}). The owner is mutated in place; the caller applies the duplicate guards and saves it.
301	     *
302	     * @param owner          the newly mapped owner about to be saved
303	     * @param ownerFieldsDto the incoming owner payload
304	     */
305	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
306	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
307	        owner.setNamesakeCount(countNamesakes(owner));
308	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
309	        assignHouseholdId(owner);
310	    }
311	
312	    /**
313	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
314	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
315	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
316	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
317	     * that predate this create; distinct owners therefore always receive distinct customer codes.
318	     *
319	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
320	     * @return the de-duplicated customer code, unique across all existing owners
321	     */
322	    private String deriveUniqueCustomerCode(Owner owner) {
323	        String base = identityKeyResolver.deriveCustomerCode(owner);
324	        Collection<Owner> existing = this.clinicService.findAllOwners();
325	        String candidate = base;
326	        int n = 2;
327	        while (isCustomerCodeInUse(candidate, existing)) {
328	            candidate = base + "-" + n;
329	            n++;
330	        }
331	        return candidate;
332	    }
333	
334	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
335	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
336	    }
337	
338	    /**
339	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
340	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
341	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
342	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
343	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
344	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
345	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
346	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
347	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
348	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
349	     * assigned (see {@link #requireUniqueIdentity}).
350	     *
351	     * @param ownerFieldsDto the incoming owner payload, mutated in place
352	     * @throws MissingOwnerFieldsException if any required field is missing or blank
353	     */
354	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
355	        normalizeAddress(ownerFieldsDto);
356	        validateRequiredFields(ownerFieldsDto);
357	        validatePostcode(ownerFieldsDto);
358	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
359	        ownerFieldsDto.setTelephone(telephone);
360	        requireCityHasCapacity(ownerFieldsDto.getCity());
361	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
362	        ownerFieldsDto.setRegistrationDate(registrationDate);
363	        requireDailyLimitNotReached(registrationDate);
364	        normalizeEmail(ownerFieldsDto);
365	    }
366	
367	    /**
368	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
369	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
370	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
371	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
372	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
373	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
374	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
375	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
376	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
377	     *
378	     * @param ownerFieldsDto the incoming owner payload, mutated in place
379	     */
380	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
381	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
382	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
383	        if (!line1.isEmpty()) {
384	            ownerFieldsDto.setAddressLine1(line1);
385	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
386	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
387	        }
388	        else {
389	            ownerFieldsDto.setAddressLine1(null);
390	            ownerFieldsDto.setAddressLine2(null);
391	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
392	        }
393	    }
394	
395	    /**
396	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
397	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
398	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
399	     * place so the caller can map and save it directly.
400	     *
401	     * @param ownerFieldsDto the incoming owner payload, mutated in place
402	     */
403	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
404	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
405	    }
406	
407	    /**
408	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
409	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
410	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
411	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
412	     * date is rejected.
413	     *
414	     * @param ownerFieldsDto the incoming owner payload
415	     * @return the effective registration date rolled forward onto a business day
416	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
417	     */
418	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
419	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
420	        if (effective == null) {
421	            effective = LocalDate.now();
422	        }
423	        else if (effective.isAfter(LocalDate.now())) {
424	            throw new FutureRegistrationDateException(
425	                "the registration date must not be later than the current server date");
426	        }
427	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
428	            || PUBLIC_HOLIDAYS.contains(effective)) {
429	            effective = effective.plusDays(1);
430	        }
431	        return effective;
432	    }
433	
434	    /**
435	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
436	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
437	     * further owner may be created for that day.
438	     *
439	     * @param registrationDate the adjusted business-day registration date of the owner being created
440	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
441	     */
442	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
443	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
444	            throw new DailyOwnerLimitExceededException(
445	                "the maximum number of owners for today has already been reached");
446	        }
447	    }
448	
449	    /**
450	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
451	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
452	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
453	     * warning threshold) so both express the same per-day count in one place.
454	     *
455	     * @param registrationDate the adjusted business-day registration date to count owners for
456	     * @return the number of existing owners registered on that day
457	     */
458	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
459	        return this.clinicService.findAllOwners().stream()
460	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
461	            .count();
462	    }
463	
464	    /**
465	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
466	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
467	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
468	     * reflects only owners that predate it.
469	     *
470	     * @param registrationDate the adjusted business-day registration date of the owner being created
471	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
472	     */
473	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
474	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
475	    }
476	
477	    /**
478	     * Counts how many existing owners already share the given owner's first and last name, compared
479	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
480	     * create; it is zero when the owner's name is unique.
481	     *
482	     * @param owner the newly mapped owner about to be saved
483	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
484	     */
485	    private int countNamesakes(Owner owner) {
486	        String firstName = owner.getFirstName();
487	        String lastName = owner.getLastName();
488	        return (int) this.clinicService.findAllOwners().stream()
489	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
490	                && lastName.equalsIgnoreCase(existing.getLastName()))
491	            .count();
492	    }
493	
494	    /**
495	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
496	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
497	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
498	     *
499	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
500	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
501	     * flat {@code address}.
502	     *
503	     * @param ownerFieldsDto the owner payload to validate
504	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
505	     */
506	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
507	        List<String> missingFields = new ArrayList<>();
508	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
509	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
510	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
511	        requireText(missingFields, "city", ownerFieldsDto.getCity());
512	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
513	        if (!missingFields.isEmpty()) {
514	            throw new MissingOwnerFieldsException(missingFields);
515	        }
516	    }
517	
518	    private void requireText(List<String> missingFields, String fieldName, String value) {
519	        if (value == null || value.isBlank()) {
520	            missingFields.add(fieldName);
521	        }
522	    }
523	
524	    /**
525	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
526	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
527	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
528	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
529	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
530	     *
531	     * @param ownerFieldsDto the incoming owner payload
532	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
533	     */
534	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
535	        String postcode = ownerFieldsDto.getPostcode();
536	        if (postcode == null) {
537	            return;
538	        }
539	        Region region = Region.forCity(ownerFieldsDto.getCity());
540	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
541	            throw new InvalidPostcodeException(
542	                "postcode " + postcode + " is not valid for the city's region " + region.name());
543	        }
544	    }
545	
546	    /**
547	     * Rejects creating an owner whose whole derived {@code identityKey} (see
548	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
549	     * duplicate only when its normalized telephone, email and last-name Soundex all match another owner's. This single
550	     * identity key is now the sole duplicate rule: because the telephone is part of the key, owners that share only
551	     * their last name and postcode but carry different telephones have distinct keys and are not caught here — they are
552	     * created and flagged as a soft match instead (see {@link #flagPossibleDuplicate}), their membership level being
553	     * capped where they join an existing household (see {@link #cappedMembershipLevel}). Owners that have been
554	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted owner
555	     * does not block the create.
556	     *
557	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
558	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
559	     */
560	    private void requireUniqueIdentity(Owner owner) {
561	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
562	        boolean inUse = this.clinicService.findAllOwners().stream()
563	            .filter(existing -> !existing.isDeleted())
564	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
565	        if (inUse) {
566	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
567	        }
568	    }
569	
570	    /**
571	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
572	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
573	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
574	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
575	     * duplicate when some existing owner shares its last-name Soundex (see {@link SoundexResolver#soundex}) and its
576	     * postcode but has a different {@code identityKey}. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
577	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
578	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
579	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
580	     *
581	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
582	     * @param ownerFieldsDto the incoming owner payload
583	     */
584	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
585	        owner.setPossibleDuplicate(false);
586	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
587	            return;
588	        }
589	        String postcode = owner.getPostcode();
590	        if (postcode == null || postcode.isBlank()) {
591	            return;
592	        }
593	        for (Owner existing : this.clinicService.findAllOwners()) {
594	            if (isPossibleDuplicateOf(owner, existing)) {
595	                owner.setPossibleDuplicate(true);
596	                owner.setPossibleDuplicateOf(existing.getId());
597	                return;
598	            }
599	        }
600	    }
601	
602	    /**
603	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner whose last-name
604	     * Soundex (see {@link SoundexResolver#soundex}) and postcode both match {@code owner}'s but whose derived
605	     * {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) differs. An equal identity key would make
606	     * the two a hard duplicate, already rejected by {@link #requireUniqueIdentity}; a differing key with a matching
607	     * name-sound and postcode — for instance two owners sharing a last name and postcode but carrying different
608	     * telephones — is the soft match this flags. The postcode-present guard is applied by the caller (see
609	     * {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
610	     *
611	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
612	     * @param existing an already-persisted owner to test the new owner against
613	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
614	     */
615	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
616	        return SoundexResolver.soundex(owner.getLastName()).equals(SoundexResolver.soundex(existing.getLastName()))
617	            && owner.getPostcode().equals(existing.getPostcode())
618	            && !identityKeyResolver.deriveIdentityKey(owner).equals(identityKeyResolver.deriveIdentityKey(existing));
619	    }
620	
621	    /**
622	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
623	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
624	     *
625	     * @param city the city of the owner being created
626	     * @throws OwnerCityFullException if the city already contains 50 or more owners
627	     */
628	    private void requireCityHasCapacity(String city) {
629	        long cityOwners = this.clinicService.findAllOwners().stream()
630	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
631	            .count();
632	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
633	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
634	        }
635	    }
636	
637	    /**
638	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
639	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
640	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
641	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
642	     * such owners never match one another as a household.
643	     *
644	     * @param owner the newly mapped owner about to be saved
645	     */
646	    private void assignHouseholdId(Owner owner) {
647	        String postcode = owner.getPostcode();
648	        if (postcode == null || postcode.isBlank()) {
649	            owner.setHouseholdId(null);
650	            return;
651	        }
652	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
653	    }
654	
655	    /**
656	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
657	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
658	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
659	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
660	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
661	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
662	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
663	     *
664	     * @param owner the owner whose capped membership level should be computed
665	     * @return the membership level, capped at one above the existing household maximum
666	     */
667	    private int cappedMembershipLevel(Owner owner) {
668	        populateHouseholdMemberCount(owner);
669	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
670	        Integer cap = householdMembershipLevelCap(owner);
671	        return cap == null ? level : Math.min(level, cap);
672	    }
673	
674	    /**
675	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
676	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
677	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
678	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
679	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
680	     * member has no cap.
681	     *
682	     * @param owner the owner whose household level cap should be computed
683	     * @return one above the existing household maximum level, or {@code null} when no cap applies
684	     */
685	    private Integer householdMembershipLevelCap(Owner owner) {
686	        String householdId = owner.getHouseholdId();
687	        Integer id = owner.getId();
688	        if (householdId == null || id == null) {
689	            return null;
690	        }
691	        Integer maxLevel = null;
692	        for (Owner member : this.clinicService.findAllOwners()) {
693	            Integer memberId = member.getId();
694	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
695	                int memberLevel = cappedMembershipLevel(member);
696	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
697	            }
698	        }
699	        return maxLevel == null ? null : maxLevel + 1;
700	    }
701	
702	    /**
703	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
704	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
705	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
706	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
707	     * already been saved it is itself among the members returned.
708	     *
709	     * @param owner the owner whose household members should be resolved
710	     * @return the members of the owner's household, never empty
711	     */
712	    private List<Owner> householdMembers(Owner owner) {
713	        String householdId = owner.getHouseholdId();
714	        if (householdId == null) {
715	            return List.of(owner);
716	        }
717	        return this.clinicService.findAllOwners().stream()
718	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
719	            .toList();
720	    }
721	
722	    /**
723	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
724	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
725	     * owner itself). An owner with no household is counted as a household of one.
726	     *
727	     * @param owner the owner whose household size should be resolved
728	     */
729	    private void populateHouseholdMemberCount(Owner owner) {
730	        owner.setHouseholdMemberCount(householdMembers(owner).size());
731	    }
732	
733	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
734	    @Override
735	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
736	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
737	        if (currentOwner == null) {
738	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
739	        }
740	        validatePostcode(ownerFieldsDto);
741	        currentOwner.setAddress(ownerFieldsDto.getAddress());
742	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
743	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
744	        currentOwner.setCity(ownerFieldsDto.getCity());
745	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
746	        currentOwner.setLastName(ownerFieldsDto.getLastName());
747	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
748	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
749	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
750	        this.clinicService.saveOwner(currentOwner);
751	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
752	    }
753	
754	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
755	    @Transactional
756	    @Override
757	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
758	        Owner owner = this.clinicService.findOwnerById(ownerId);
759	        if (owner == null) {
760	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
761	        }
762	        owner.setDeleted(true);
763	        this.clinicService.saveOwner(owner);
764	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
765	    }
766	
767	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
768	    @Override
769	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
770	        Owner owner = this.clinicService.findOwnerById(ownerId);
771	        if (owner == null) {
772	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
773	        }
774	        HttpHeaders headers = new HttpHeaders();
775	        Pet pet = petMapper.toPet(petFieldsDto);
776	        owner.setId(ownerId);
777	        pet.setOwner(owner);
778	        pet.getType().setName(null);
779	        this.clinicService.savePet(pet);
780	        PetDto petDto = petMapper.toPetDto(pet);
781	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
782	            .buildAndExpand(pet.getId()).toUri());
783	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
784	    }
785	
786	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
787	    @Override
788	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
789	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
790	        if (currentOwner != null) {
791	            Pet currentPet = this.clinicService.findPetById(petId);
792	            if (currentPet != null) {
793	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
794	                currentPet.setName(petFieldsDto.getName());
795	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
796	                this.clinicService.savePet(currentPet);
797	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
798	            }
799	        }
800	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
801	    }
802	
803	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
804	    @Override
805	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
806	        HttpHeaders headers = new HttpHeaders();
807	        Visit visit = visitMapper.toVisit(visitFieldsDto);
808	        Pet pet = new Pet();
809	        pet.setId(petId);
810	        visit.setPet(pet);
811	        this.clinicService.saveVisit(visit);
812	        VisitDto visitDto = visitMapper.toVisitDto(visit);
813	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
814	            .buildAndExpand(visit.getId()).toUri());
815	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
816	    }
817	
818	
819	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
820	    @Override
821	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
822	        Owner owner = this.clinicService.findOwnerById(ownerId);
823	        if (owner != null) {
824	            Pet pet = owner.getPet(petId);
825	            if (pet != null) {
826	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
827	            }
828	        }
829	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
830	    }
831	}
